mapper.select:
SELECT id, parent_unit_id AS parentUnitId, unit_kind AS unitKind, title, sort_order AS sortOrder,
  (SELECT COUNT(*) FROM edu_course_unit c WHERE c.course_space_id=#{courseId} AND c.parent_unit_id=#{id}) AS childCount
FROM edu_course_unit WHERE course_space_id=#{courseId} AND id=#{id}
